package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.graphics.*;import android.os.Bundle;import android.view.*;import android.widget.*;import java.util.*;
public final class ThemePacksActivity extends LeoActivity {
 private int selected,tab;private View previewRoot;
 protected void onCreate(Bundle b){super.onCreate(b);home();}
 private void home(){ArrayList<String> rows=new ArrayList<String>(Arrays.asList(ThemePacks.NAMES));rows.add(L.t("Restabilește aspectul anterior"));list(L.t("Colecții vizuale"),rows,selected,new Choice(){public void pick(int n){if(n<ThemePacks.NAMES.length){selected=n;tab=0;preview();}else options(L.t("Restabilești culorile, fontul și fundalul?"),new String[]{L.t("Păstrează"),L.t("Restabilește")},new Choice(){public void pick(int yes){if(yes==1)worker.execute(new Runnable(){public void run(){try{ThemeCheckpoint.restore(ThemePacksActivity.this);ui(new Runnable(){public void run(){notice(L.t("Aspect restabilit"));home();}});}catch(Exception e){ui(new Runnable(){public void run(){notice(L.t("Nu există o copie vizuală validă"));}});}}});}});}},"",null);}
 private void preview(int n){selected=Math.floorMod(n,ThemePacks.NAMES.length);tab=0;preview();}
 private void preview(){final Appearance.Palette sample=new Appearance.Palette(Appearance.COLORS[ThemePacks.THEMES[selected]]);begin(ThemePacks.NAMES[selected]);previewRoot=root;root.addView(new View(this){final Paint p=new Paint(3);
        final LockScreenArt lockArt = tab == 3 ? new LockScreenArt(ThemePacksActivity.this) : null;
        final HomeCards.Card lockWeather = new HomeCards.Card(0, L.t("Meteo · ") + L.t("București"),
            "18°C · " + L.t("Senin"), "Cache · 12:30", 0, System.currentTimeMillis());
        void box(Canvas c,int x,int y,int w,int h,int color){p.setColor(color);c.drawRoundRect(x,y,x+w,y+h,6,6,p);}void label(Canvas c,String s,int x,int y,int size,int color){p.setColor(color);p.setTextSize(size);p.setTypeface(Typeface.create("sans-serif-medium",0));c.drawText(s,x,y,p);}void badge(Canvas c,String name,int x,int y){AppBadge icon=new AppBadge(name,36);icon.setBounds(x,y,x+36,y+36);icon.draw(c);}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/224f);c.drawColor(sample.background);label(c,new String[]{L.t("ACASĂ"),"MENIU","PLAYER","BLOCARE"}[tab]+L.t(" · mostră ")+(tab+1)+"/4",10,20,14,sample.accent);if(tab==0){label(c,"12:40",18,68,36,Color.WHITE);label(c,L.t("Joi"),20,90,14,sample.accent);box(c,10,108,220,46,sample.card);label(c,L.t("Meteo · 18° · senin"),20,137,16,Color.WHITE);badge(c,L.t("Telefon"),25,168);badge(c,L.t("Mesaje"),100,168);badge(c,L.t("Muzică"),177,168);}else if(tab==1&&sample.sxmo()){String[] items={"Terminal","Apps","Games","Files","Phone","Call log","Messages","Contacts"};for(int i=0;i<items.length;i++){int y=44+i*22;if(i==2){p.setColor(sample.selection);c.drawRect(0,y-16,240,y+5,p);}SxmoIcon icon=new SxmoIcon(i==0?23:i==3?7:i==4?0:i==6?2:i==7?1:9,16);icon.setBounds(5,y-13,21,y+3);icon.draw(c);label(c,items[i],27,y,17,Color.WHITE);}}else if(tab==1){String[] names={L.t("Telefon"),L.t("Contacte"),L.t("Mesaje"),L.t("Ceas"),L.t("Muzică"),L.t("Setări")};for(int i=0;i<6;i++){int x=14+i%3*76,y=40+i/3*82;if(i==1)box(c,x-4,y-4,69,75,sample.selection);badge(c,names[i],x+11,y);label(c,names[i],x,y+59,12,i==1?sample.ink:Color.WHITE);}}else if(tab==2){box(c,10,38,220,128,sample.card);p.setColor(sample.accent);c.drawCircle(65,96,39,p);p.setColor(sample.background);c.drawCircle(65,96,11,p);label(c,L.t("Muzică"),116,86,16,Color.WHITE);label(c,L.t("Colecția ta"),116,111,12,sample.accent);box(c,15,179,210,5,sample.card);box(c,15,179,95,5,sample.accent);label(c,"01:24       ◀  ▶       03:18",20,211,13,Color.WHITE);}else{
            c.scale(1, 224f / 320f);
            lockArt.background(c, sample, null);
            lockArt.text(c, L.t("Taste blocate"), 12, 22, 12, sample.accent, Paint.Align.LEFT, 126);
            lockArt.battery(c, 78, false);
            lockArt.clock(c, "12:40", L.t("Joi"), 0);
            lockArt.weather(c, sample, lockWeather);
            lockArt.panel(c, sample.bar, 12, 293, 228, 316, 7);
            lockArt.text(c, L.t("Deblocare"), 120, 309, 13, Color.WHITE, Paint.Align.CENTER, 204);
        }c.restore();}},new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){options(L.t("Aplici colecția?"),new String[]{L.t("Păstrează stilul actual"),L.t("Pachet complet · culori, font, fundal"),L.t("Doar culori în toate aplicațiile")},new Choice(){public void pick(final int yes){if(yes==0)return;worker.execute(new Runnable(){public void run(){try{ThemeCheckpoint.apply(ThemePacksActivity.this,selected,yes==1);ui(new Runnable(){public void run(){notice(L.t("Tema aplicată"));home();}});}catch(Exception e){ui(new Runnable(){public void run(){notice(L.t("Tema nu a putut fi aplicată"));}});}}});}});}};back=new Runnable(){public void run(){home();}};footer(L.t("Aplică"),L.t("← / → mostră"),L.t("Înapoi"));}
 public boolean onKeyDown(int code,KeyEvent e){if(root==previewRoot&&(code==21||code==22)){if(e.getRepeatCount()==0){tab=Math.floorMod(tab+(code==22?1:-1),4);preview();}return true;}return super.onKeyDown(code,e);}
}
